package dao; import dto.PostDTO; import util.DBConnection; import java.sql.*; import java.util.*;
public class BookmarkDAO {
public boolean exists(long m,long p)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("SELECT 1 FROM bookmark WHERE member_id=? AND post_id=?")){q.setLong(1,m);q.setLong(2,p);try(ResultSet r=q.executeQuery()){return r.next();}}}
public boolean toggle(long m,long p)throws Exception{boolean e=exists(m,p);String s=e?"DELETE FROM bookmark WHERE member_id=? AND post_id=?":"INSERT INTO bookmark(member_id,post_id) VALUES(?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement(s)){q.setLong(1,m);q.setLong(2,p);q.executeUpdate();return !e;}}
public List<PostDTO> selectPostsByMemberId(long m)throws Exception{List<PostDTO>a=new ArrayList<>();String s="SELECT p.*,me.nickname member_nickname,c.name category_name,(SELECT COUNT(*) FROM comment cm WHERE cm.post_id=p.post_id) comment_count FROM bookmark b JOIN post p ON b.post_id=p.post_id JOIN member me ON p.member_id=me.member_id LEFT JOIN category c ON p.category_id=c.category_id WHERE b.member_id=? ORDER BY b.created_at DESC";try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement(s)){q.setLong(1,m);try(ResultSet r=q.executeQuery()){while(r.next()){PostDTO x=new PostDTO();x.setPostId(r.getLong("post_id"));x.setMemberId(r.getLong("member_id"));x.setCategoryId(r.getInt("category_id"));x.setBoardType(r.getString("board_type"));x.setTitle(r.getString("title"));x.setContent(r.getString("content"));x.setViewCount(r.getInt("view_count"));x.setLikeCount(r.getInt("like_count"));x.setCommentCount(r.getInt("comment_count"));x.setCreatedAt(r.getTimestamp("created_at"));x.setMemberNickname(r.getString("member_nickname"));x.setCategoryName(r.getString("category_name"));a.add(x);}}}return a;}}
